// Package bpf holds the compiled eBPF programs, generated by bpf2go at build
// time (see the Dockerfile). The target kernel is DSM 7.2's 4.4.302+, so the
// C is compiled for the v1 instruction set with no BTF/CO-RE dependencies.
package bpf

//go:generate go run github.com/cilium/ebpf/cmd/bpf2go -cc clang -cflags "-O2 -g -Wall -Werror -mcpu=v1" -target amd64 Filetop ../../bpf/filetop.c -- -I../../bpf
